head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd   = ""; // 조회조건 기업코드

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00307.onpageload" });
    }
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 *  팝업호출
 */
scwin.grd_RetiPayAlwnc_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if (columnId === "basYymm") {
          scwin.retiPayAlwncDtlSrchOpen(rowIndex);  // 퇴직급여충당금 상세  팝업 오픈
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00307.grd_RetiPayAlwnc_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 *  화면 초기화
 */
scwin.init = function() {
    scwin.search();
};

/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dlt_RetiPayAlwncRes.removeAll();
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd=== "") {
        return false;
    }
    return true;
};

/**
 * 퇴직급여충당금 조회
 */
scwin.search = function() {

    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    let url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/retirement-benefits";
    $c.sbm.setAction(sbm_dlt_RetiPayAlwnc, url);
    $c.sbm.execute(sbm_dlt_RetiPayAlwnc);
};

/**
 * 퇴직급여충당금 상세 팝업
 */
scwin.retiPayAlwncDtlSrchOpen = function(pRow) {

    console.log(pRow);
    let url = "/ui/lst/fis/ULDFIS00300_P5.xml";
    let popTitle = "퇴직급여 충담금 검색";

    const opts = {
        id: "ULDFIS00300_P5",
        popupName: popTitle,
        width: 700,
        height: 600,
        frameModal: "top",
    };

    const popData = dlt_RetiPayAlwncRes.getRowJSON(pRow);
    $c.win.openPopup(url, opts, popData);

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {
    if (dlt_RetiPayAlwncRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_RetiPayAlwnc, {fileName: "퇴직급여충당금", type: "8"});
};
